/// Whether `got` is `want` to `f32` precision.
#[cfg(any(
    feature = "ax",
    feature = "mx",
    feature = "pro",
    feature = "rx",
    feature = "x-series",
    feature = "y-series"
))]
fn close(got: f32, want: f32) -> bool {
    (got - want).abs() <= 1e-5 * want.abs().max(1.0)
}

/// The Tier 1 lookup of a role finds the Tier 2 trait's register.
#[cfg(any(
    feature = "ax",
    feature = "mx",
    feature = "pro",
    feature = "rx",
    feature = "x-series",
    feature = "y-series"
))]
fn same_role(
    found: Option<&crate::actuator::RoleRegister>,
    tier2: crate::actuator::RoleRegister,
    register: crate::register::Register,
    name: &str,
) {
    assert_eq!(found, Some(&tier2), "{name}");
    assert_eq!(tier2.register(), register, "{name}");
    assert_eq!(
        (tier2.address(), tier2.size()),
        (register.addr, register.size),
        "{name}"
    );
    assert_eq!(tier2.name(), name);
}

#[test]
fn unknown_model_number() {
    let id = id();
    for protocol in [ProtocolVersion::P1, ProtocolVersion::P2] {
        let found = ActuatorKind::new(protocol, ModelNumber(65535), 0, id);
        let error = SetupError::UnsupportedModel {
            id,
            model_number: 65535,
            protocol,
            feature: None,
        };
        assert_eq!(found, Err(error));
        assert_eq!(
            ActuatorKind::firmware_register(protocol, ModelNumber(65535)),
            None
        );
    }
}

